package checkpoint

import (
	"fmt"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

var (
	_ PersistentStore = (*GitStore)(nil)
	_ AuthorReader    = (*GitStore)(nil)
	_ Writer          = (*GitStore)(nil)
	_ EphemeralStore  = (*ephemeralStore)(nil)
)

// treeWriter holds the repo-only machinery for building a single checkpoint's
// subtree from write requests: entry builders, transcript/session writers, and
// the per-request appliers (applySessionWrite / applyTranscriptBackfill /
// applySummaryBackfill / applyAttributionBackfill). It is independent of where
// the resulting subtree is committed, so both the git-branch store (which nests
// the subtree under <shard>/<id>/ on the v1 branch) and the git-refs store
// (which keeps it at the root of a per-checkpoint ref) embed it and share this
// code.
type treeWriter struct {
	repo *git.Repository
}

// GitStore is the committed (persistent) checkpoint store. Writes target
// refs.Primary; committed reads resolve against refs.Read. The temporary
// shadow-branch surface lives in ephemeralStore. It embeds *treeWriter for the
// shared subtree-building machinery.
type GitStore struct {
	*treeWriter

	refs        PersistentRefs
	blobFetcher BlobFetchFunc
}

// ephemeralStore is the git shadow-branch (temporary) checkpoint store. It is
// an independent type from GitStore; the two share only package-level helpers.
type ephemeralStore struct {
	repo *git.Repository
	refs PersistentRefs
}

// newEphemeralStore creates the shadow-branch store for the given repository
// and committed-metadata topology (it consults refs.Primary to recognize the
// committed branch when listing shadow branches).
func newEphemeralStore(repo *git.Repository, refs PersistentRefs) *ephemeralStore {
	return &ephemeralStore{repo: repo, refs: refs}
}

// NewEphemeralStore constructs the git shadow-branch (temporary) checkpoint
// store. Most callers reach it via Open(...).Ephemeral(); this direct
// constructor exists for benchmarks and tests that exercise the shadow-branch
// surface without the full facade.
func NewEphemeralStore(repo *git.Repository, refs PersistentRefs) EphemeralStore {
	return newEphemeralStore(repo, refs)
}

// NewGitStore creates a checkpoint store backed by the given git repository
// and committed-metadata topology. Pass DefaultV1Refs() for the v1-only default
// or ResolveRefs(ctx) in code paths that honor settings.
func NewGitStore(repo *git.Repository, refs PersistentRefs) *GitStore {
	return &GitStore{treeWriter: &treeWriter{repo: repo}, refs: refs}
}

// SetBlobFetcher configures the store to automatically fetch missing blobs
// on demand when reading from metadata trees.
func (s *GitStore) SetBlobFetcher(f BlobFetchFunc) {
	s.blobFetcher = f
}

// Repository returns the underlying git repository.
func (s *GitStore) Repository() *git.Repository {
	return s.repo
}

// Refs returns the committed-metadata topology the store was constructed with.
func (s *GitStore) Refs() PersistentRefs {
	return s.refs
}

// PersistentReadRef returns the ref that committed-checkpoint reads resolve against.
func (s *GitStore) PersistentReadRef() plumbing.ReferenceName {
	return s.refs.Read
}

func (s *GitStore) setPrimaryRef(hash plumbing.Hash) error {
	if err := s.repo.Storer.SetReference(plumbing.NewHashReference(s.refs.Primary, hash)); err != nil {
		return fmt.Errorf("set primary metadata ref %s to %s: %w", s.refs.Primary, hash, err)
	}
	return nil
}
package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"

	"github.com/go-git/go-git/v6"
)

// BackendTypeGitBranch is the built-in git-branch checkpoint backend: it stores
// the committed record on a git branch (entire/checkpoints/v1) in this repo. It
// is git-backed (see registeredBackend.gitBacked) and is the default primary
// when no backend is configured.
const BackendTypeGitBranch = "git-branch"

// BackendTypeGitRefs is the built-in git-refs checkpoint backend: it stores the
// committed record as one git ref per checkpoint (refs/entire/checkpoints/<shard>/
// <id>) in this repo. Like git-branch it is git-backed, so it may be the primary;
// the two can run side by side (git-refs primary + git-branch mirror) during the
// branch->refs rollout, since the one-of-each-type rule permits distinct
// git-backed backends in the same topology.
const BackendTypeGitRefs = "git-refs"

// OpenEnv carries the construction context a backend factory may need.
// Git-backed backends require Repo and use Refs/BlobFetcher/RefFetcher; other
// backends ignore the git-shaped fields and read their own configuration from cfg.
type OpenEnv struct {
	Repo        *git.Repository
	BlobFetcher BlobFetchFunc
	RefFetcher  RefFetchFunc
	Refs        PersistentRefs
}

// Factory constructs a persistent store for one backend type. cfg is the
// backend-specific JSON "config" block from settings (nil when absent).
type Factory func(ctx context.Context, env OpenEnv, cfg json.RawMessage) (PersistentStore, error)

// registeredBackend is a factory plus the capabilities the topology layer needs.
type registeredBackend struct {
	factory Factory
	// gitBacked reports whether the backend stores the committed record in this
	// repo's git object store. Only git-backed backends may be the primary,
	// because the checkpoint lifecycle (resume bootstrap, doctor reconcile,
	// explain tree-read, push, cleanup, pre-push OPF) drives the primary's record
	// through the repo and its refs — see buildPrimary. A backend that is not
	// git-backed has no such ref for those paths to operate on, so it is
	// mirror-only (write fan-out) until that lifecycle moves behind the store.
	// Whether a backend may be a *mirror* is governed separately by the
	// one-of-each-type topology rule in buildMirrors, not by this flag (a
	// git-backed backend can mirror alongside a different git-backed primary).
	gitBacked bool
}

var (
	registryMu sync.RWMutex
	// registry maps backend type to its factory and capabilities. Git-backed
	// backends are built in (registered here). Other backends add themselves
	// through Register — in practice only test-only backends do, via their
	// RegisterForTesting helpers, so a production binary can never select them.
	registry = map[string]registeredBackend{
		BackendTypeGitBranch: {factory: gitBranchBackendFactory, gitBacked: true},
		BackendTypeGitRefs:   {factory: gitRefsBackendFactory, gitBacked: true},
	}
)

// Register adds a non-git-backed backend factory under typ. Such backends can
// serve as mirrors but not as the primary (see registeredBackend.gitBacked).
// Git-backed backends are built in and not registered through this path. It
// panics on a duplicate type to surface wiring mistakes.
func Register(typ string, f Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	if _, exists := registry[typ]; exists {
		panic(fmt.Sprintf("checkpoint: backend type %q already registered", typ))
	}
	registry[typ] = registeredBackend{factory: f, gitBacked: false}
}

// lookupBackend returns the registered backend for typ, or a clear error
// (naming the registered types) when the type is unknown.
func lookupBackend(typ string) (registeredBackend, error) {
	registryMu.RLock()
	b, ok := registry[typ]
	registryMu.RUnlock()
	if !ok {
		return registeredBackend{}, fmt.Errorf("unknown checkpoint backend type %q (registered: %s)", typ, registeredTypes())
	}
	return b, nil
}

// ValidatePrimaryBackend reports an error unless typ names a registered backend
// that may serve as the primary. An unknown type is rejected with an error
// listing the registered backend types; a registered but non-git-backed type is
// rejected separately, since only git-backed backends may be the primary. This
// is the single source of the "primary must be git-backed" rule — buildPrimary
// delegates here, and selection surfaces (entire enable / configure
// --checkpoint-backend) call it to reject a bad backend before writing it to
// settings, rather than failing later in Open.
func ValidatePrimaryBackend(typ string) error {
	b, err := lookupBackend(typ)
	if err != nil {
		return err
	}
	if !b.gitBacked {
		return fmt.Errorf("checkpoint backend %q cannot be the primary: only git-backed backends (e.g. %q, %q) may be the primary", typ, BackendTypeGitBranch, BackendTypeGitRefs)
	}
	return nil
}

// build constructs the store for the named backend type.
func build(ctx context.Context, env OpenEnv, typ string, cfg json.RawMessage) (PersistentStore, error) {
	b, err := lookupBackend(typ)
	if err != nil {
		return nil, err
	}
	store, err := b.factory(ctx, env, cfg)
	if err != nil {
		return nil, fmt.Errorf("construct %q checkpoint backend: %w", typ, err)
	}
	return store, nil
}

func registeredTypes() string {
	registryMu.RLock()
	defer registryMu.RUnlock()
	types := make([]string, 0, len(registry))
	for t := range registry {
		types = append(types, t)
	}
	sort.Strings(types)
	return strings.Join(types, ", ")
}

// gitBranchBackendFactory builds the git-branch persistent store from the open
// environment. It ignores cfg: git topology comes from env.Refs, not settings.
func gitBranchBackendFactory(_ context.Context, env OpenEnv, _ json.RawMessage) (PersistentStore, error) {
	if env.Repo == nil {
		return nil, errors.New("git-branch checkpoint backend requires a repository")
	}
	store := NewGitStore(env.Repo, env.Refs)
	if env.BlobFetcher != nil {
		store.SetBlobFetcher(env.BlobFetcher)
	}
	return store, nil
}

// gitRefsBackendFactory builds the git-refs persistent store from the open
// environment. It ignores cfg and env.Refs: each checkpoint resolves its own ref
// (refs/entire/checkpoints/<shard>/<id>) rather than a single configured ref.
func gitRefsBackendFactory(_ context.Context, env OpenEnv, _ json.RawMessage) (PersistentStore, error) {
	if env.Repo == nil {
		return nil, errors.New("git-refs checkpoint backend requires a repository")
	}
	store := newGitRefsStore(env.Repo)
	if env.BlobFetcher != nil {
		store.SetBlobFetcher(env.BlobFetcher)
	}
	if env.RefFetcher != nil {
		store.SetRefFetcher(env.RefFetcher)
	}
	return store, nil
}
package checkpoint

import (
	"context"
	"errors"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// kindRoutingStore resolves id-keyed reads across the two git backends so a repo
// running git-refs and git-branch side by side (or mid-migration between them)
// can read checkpoints of BOTH formats without reconfiguring:
//
//   - A ULID checkpoint only ever lives in the git-refs store, so a ULID ID is
//     read from refs and NEVER from the branch (regardless of the active backend).
//   - A legacy-hex ID is read from the active (configured) primary first. When the
//     active primary is git-refs, it also falls back to the git-branch store,
//     because a hex checkpoint may still sit on the pre-migration v1 branch. Under
//     a git-branch primary the branch is authoritative for hex, so refs is not
//     consulted.
//
// List unions both backends (disjoint ID spaces). Writes are NOT kind-routed:
// they go to the configured primary (+ mirrors) via writer, since a new
// checkpoint's ID is already minted to match the primary's format
// (see checkpoint.GenerateCheckpointID).
type kindRoutingStore struct {
	writer      PersistentStore // configured primary + mirrors (fanout); handles Write
	branch      PersistentStore // git-branch store; serves hex reads
	refs        PersistentStore // git-refs store; serves ULID reads (+ hex under refs primary)
	primaryType string
}

// newKindRoutingStore wraps the write fanout plus the two git read stores. It
// preserves the optional AuthorReader capability (explain relies on it) when both
// read stores provide it — the built-in git backends always do.
func newKindRoutingStore(writer, branch, refs PersistentStore, primaryType string) PersistentStore {
	s := &kindRoutingStore{writer: writer, branch: branch, refs: refs, primaryType: primaryType}
	if _, ok := branch.(AuthorReader); ok {
		if _, ok := refs.(AuthorReader); ok {
			return &kindRoutingStoreWithAuthor{kindRoutingStore: s}
		}
	}
	return s
}

// readOrder returns the stores to consult for checkpointID, in priority order,
// per the routing rules above.
func (s *kindRoutingStore) readOrder(checkpointID id.CheckpointID) []PersistentStore {
	if checkpointID.Kind() == id.KindULID {
		return []PersistentStore{s.refs} // ULIDs only ever live in refs
	}
	switch s.primaryType {
	case BackendTypeGitBranch:
		return []PersistentStore{s.branch} // branch is authoritative for hex
	case BackendTypeGitRefs:
		return []PersistentStore{s.refs, s.branch} // active refs, then pre-migration branch
	default:
		// A non-branch/refs git-backed primary is not a real configuration today;
		// try both git stores so a hex ID still resolves wherever it landed.
		return []PersistentStore{s.branch, s.refs}
	}
}

// firstResolved calls read on each store in order and returns the first genuine
// hit (a non-absent result with no error). A non-final store that reports absent
// OR errors falls through to the next store, so a transient failure in one
// backend (e.g. a git-refs on-demand fetch error) does not hide a checkpoint that
// resolves in the fallback backend. The final store's result is returned as-is
// (hit, absent, or error), so callers still see the backend's own not-found /
// error signal when nothing resolved.
func firstResolved[T any](stores []PersistentStore, read func(PersistentStore) (T, error), absent func(T, error) bool) (T, error) {
	var v T
	var err error
	for i, st := range stores {
		v, err = read(st)
		if i == len(stores)-1 || (err == nil && !absent(v, err)) {
			return v, err
		}
	}
	return v, err
}

// checkpointNotFound reports the checkpoint-level "absent" signal: Read returns
// (nil, nil) — not an error — when a checkpoint does not exist.
func checkpointNotFound(v *CheckpointSummary, err error) bool {
	return err == nil && v == nil
}

// sessionNotFound reports the session-level "absent" signal: the session readers
// return ErrCheckpointNotFound when the checkpoint (or session) is missing.
func sessionNotFound[T any](_ T, err error) bool {
	return errors.Is(err, ErrCheckpointNotFound)
}

func (s *kindRoutingStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	return firstResolved(s.readOrder(checkpointID),
		func(st PersistentStore) (*CheckpointSummary, error) { return st.Read(ctx, checkpointID) },
		checkpointNotFound,
	)
}

func (s *kindRoutingStore) List(ctx context.Context) ([]CheckpointInfo, error) {
	branchList, err := s.branch.List(ctx)
	if err != nil {
		return nil, err //nolint:wrapcheck // in-package store error surfaced verbatim
	}
	refsList, err := s.refs.List(ctx)
	if err != nil {
		return nil, err //nolint:wrapcheck // in-package store error surfaced verbatim
	}
	merged := make([]CheckpointInfo, 0, len(branchList)+len(refsList))
	merged = append(merged, branchList...)
	merged = append(merged, refsList...)
	sortCheckpointInfosByRecency(merged)
	// Dedup by ID: during coexistence/migration the same checkpoint can appear in
	// both backends (a ULID mirrored to the branch, or a hex still on the branch
	// and also migrated into refs). Keep the first occurrence — i.e. the most
	// recent after the sort.
	deduped := merged[:0]
	seen := make(map[id.CheckpointID]struct{}, len(merged))
	for _, info := range merged {
		if _, dup := seen[info.CheckpointID]; dup {
			continue
		}
		seen[info.CheckpointID] = struct{}{}
		deduped = append(deduped, info)
	}
	return deduped, nil
}

// sortCheckpointInfosByRecency orders checkpoints most-recent-first by CreatedAt.
// Shared by the git-branch, git-refs, and routing List implementations so they
// present a consistent order.
func sortCheckpointInfosByRecency(checkpoints []CheckpointInfo) {
	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
	})
}

func (s *kindRoutingStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
	return firstResolved(s.readOrder(checkpointID),
		func(st PersistentStore) (*SessionContent, error) {
			return st.ReadSessionContent(ctx, checkpointID, sessionIndex)
		},
		sessionNotFound[*SessionContent],
	)
}

func (s *kindRoutingStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error) {
	return firstResolved(s.readOrder(checkpointID),
		func(st PersistentStore) (*Metadata, error) {
			return st.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
		},
		sessionNotFound[*Metadata],
	)
}

func (s *kindRoutingStore) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
	return firstResolved(s.readOrder(checkpointID),
		func(st PersistentStore) (string, error) {
			return st.ReadSessionPrompts(ctx, checkpointID, sessionIndex)
		},
		sessionNotFound[string],
	)
}

// metaAndPrompts bundles the two non-error returns of ReadSessionMetadataAndPrompts
// so it can flow through the single-value firstResolved helper.
type metaAndPrompts struct {
	meta    *Metadata
	prompts string
}

func (s *kindRoutingStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error) {
	mp, err := firstResolved(s.readOrder(checkpointID),
		func(st PersistentStore) (metaAndPrompts, error) {
			m, p, e := st.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
			return metaAndPrompts{meta: m, prompts: p}, e //nolint:wrapcheck // in-package store error surfaced verbatim
		},
		sessionNotFound[metaAndPrompts],
	)
	return mp.meta, mp.prompts, err
}

// Write is not kind-routed: it targets the configured primary (+ mirrors).
func (s *kindRoutingStore) Write(ctx context.Context, req WriteRequest) error {
	return s.writer.Write(ctx, req) //nolint:wrapcheck // primary error is the operation's error, surfaced verbatim
}

// kindRoutingStoreWithAuthor adds the optional AuthorReader capability, routing
// GetCheckpointAuthor by the same rules as the reads.
type kindRoutingStoreWithAuthor struct {
	*kindRoutingStore
}

func (s *kindRoutingStoreWithAuthor) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
	return firstResolved(s.readOrder(checkpointID),
		func(st PersistentStore) (Author, error) {
			ar, ok := st.(AuthorReader)
			if !ok {
				return Author{}, nil
			}
			return ar.GetCheckpointAuthor(ctx, checkpointID)
		},
		func(a Author, err error) bool { return err == nil && a == Author{} },
	)
}

